/* Culture-led, place-specific psychological investigations for the World Atlas. */
import {CULTURE_ARTICLES} from './ns-cultural-atlas-articles.mjs';
const LOCAL={"washoku":[{"kind":"Local psychology study","title":"The Relationship between Family Meals and Mental Health Problems in Japanese Elementary School Children","citation":"International Journal of Environmental Research and Public Health (2021)","url":"https://pubmed.ncbi.nlm.nih.gov/34501870/","method":"Cross-sectional questionnaire study of 678 children aged 7–12 in Gifu Prefecture.","finding":"Family-meal frequency was associated with children’s measured mental-health status. This Japanese sample provides a local point of comparison while leaving direction and the roles of conversation or household circumstances open."},{"kind":"Japanese family psychology study","title":"Family Communication During Meals and Parent–Child Psychological Connection","citation":"Japanese Association of Family Psychology (2001)","url":"https://www.jstage.jst.go.jp/article/jafp/15/2/15_125/_article/-char/en","method":"Questionnaires from 77 fifth- and sixth-grade children and their parents.","finding":"Children who described healthier family relationships also tended to describe mealtime as more positive and psychologically connected."}],"ainu-dance":[{"kind":"Hokkaidō field study","title":"Record and Transmission for Traditional Ainu Dance: The Case Study of Mukawa Ainu","citation":"Japanese Journal of Dance Research (2019)","url":"https://www.jstage.jst.go.jp/article/buyougaku/2019/42/2019_01/_article/-char/en","method":"Field research with the Mukawa Ainu cultural preservation organization.","finding":"The study follows how recognition of Ainu dance relates to local revitalisation and considers how documentation can support teaching between generations."},{"kind":"Sapporo ethnography","title":"What Does Ainu Cultural Revitalisation Mean to Ainu and Wajin Youth?","citation":"AlterNative (2019)","url":"https://journals.sagepub.com/doi/10.1177/1177180119846665","method":"Fieldwork with Urespa, a place for learning Ainu culture in Sapporo, in 2016.","finding":"The case study examines how Ainu cultural practice is being rebuilt in a contemporary urban setting and makes self-determination part of the account."}],"day-of-dead":[{"kind":"Mexican child psychology study","title":"How Cultural Practices Influence Mexican Children’s Memories of Death Events","citation":"Psychological Reports (2024)","url":"https://pubmed.ncbi.nlm.nih.gov/39180510/","method":"Study of 43 children in Puebla, comparing memories of death events with other negative memories and assessing biological and spiritual understandings of death.","finding":"Children’s understandings included both biological and spiritual components, showing how more than one explanatory model can be used in a local cultural setting."},{"kind":"Puebla mixed-methods study","title":"Embracing Death: Mexican Parent and Child Perspectives on Death","citation":"Child Development (2020)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6883122/","method":"Quantitative child measures paired with qualitative analysis of parents’ open responses; the project also included participant observation during Día de los Muertos in Puebla.","finding":"The study records children’s questions about death and parents’ accounts of answering them through family conversation and local ritual."}],"capoeira":[{"kind":"Salvador mental-health service study","title":"The Body in Capoeira and Its Contribution to Cultural Identity among CAPS-II Service Users","citation":"Federal University of Sergipe dissertation (2024)","url":"https://ri.ufs.br/handle/riufs/20713","method":"Descriptive qualitative study based on weekly capoeira workshops and documentary analysis with five users of a psychosocial care centre in Salvador, Bahia.","finding":"The author examines how an Afro-Brazilian embodied practice was experienced in relation to cultural identity among people receiving mental-health care."}],"kente":[{"kind":"Bonwire craft study","title":"Spirituality in Creative Work: How Craft Entrepreneurs in Ghana Cope with Precarity","citation":"International Journal of Cultural Policy (2024)","url":"https://www.tandfonline.com/doi/full/10.1080/09548963.2024.2404627","method":"Interview-based research involving Kente makers in Bonwire, Ashanti Region.","finding":"The paper connects craft work, spiritual meaning and economic uncertainty, placing Kente within makers’ working lives rather than treating cloth only as a symbol."}],"castells":[{"kind":"Lleida casteller study","title":"The Social Construction of Emotions in Castellers","citation":"University of Lleida research (2022)","url":"https://portalrecerca.udl.cat/documentos/67c9f5f5c5b377209b356700?lang=es","method":"Ethnomotric qualitative study of the Castellers de Lleida group.","finding":"The study asks how the practice creates and organises emotional experience within a specific castell community."},{"kind":"Catalonia ethnography","title":"Castells in the Construction of a Catalan Community","citation":"Ethnographic research (2019)","url":"https://escholarship.org/uc/item/7v0350x8","method":"Ethnographic account of why people from socially and linguistically diverse backgrounds join casteller teams.","finding":"The account follows how team participation can shape what Catalan community means to people who join."},{"kind":"Catalonia human-tower psychology study","title":"The Emotional States Elicited in a Human Tower Performance: Case Study","citation":"Frontiers in Psychology (2021)","url":"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.611279/full","method":"Mixed-method ethnographic case study with 17 Castellers de Lleida informants, participant observation, interviews and analysis of 132 comments during a performance in Paeria Square.","finding":"Seventy comments (53%) described well-being, 49 (37.1%) discomfort and 13 (9.8%) affect in general. Joy clustered around a successful tower and shared effort; nervousness rose during the public climb and shifted after completion.","quote":"When the 3d8 finishes you feel very happy, satisfied, very proud.","quoteAttribution":"Casteller E.5, interviewed in the Lleida human-tower study."}],"argan":[{"kind":"Souss-Massa regional study","title":"Pathways to Women’s Empowerment and Social Inclusion through Cooperative Entrepreneurship","citation":"Annals of Public and Cooperative Economics (2025)","url":"https://onlinelibrary.wiley.com/doi/full/10.1111/apce.70004","method":"Quantitative study of 558 women belonging to cooperatives in Morocco’s Souss-Massa region.","finding":"The authors report links between cooperative entrepreneurship and psychological, economic and social dimensions of empowerment and inclusion."}],"fado":[{"kind":"Lisbon ethnography","title":"Fado, Spirituality and Healing: Sensing, Performing and Embodying Emotion in Lisbon","citation":"Trabalhos de Antropologia e Etnologia (2022)","url":"https://repositorio.iscte-iul.pt/bitstream/10071/24088/1/article_85324.pdf","method":"Long-term Lisbon fieldwork and auto-ethnography centred on fado vadio at Tasca do Jaime, including the biography of singer João and interactions among fadistas, regulars and visitors.","finding":"The study follows how sensory attention, vocal delivery, bodily expression and audience response can make a performance feel sacred or healing to some participants, within Lisbon’s changing religious life.","quote":"Fado is sacred, would you talk in a church? Please have respect.","quoteAttribution":"Tasca owner Laura, as quoted in Roussou’s Lisbon fieldwork."}],"rebetiko":[{"kind":"Piraeus ethnography","title":"Rebetiko Neighbourhoods: Musical Encounters and Social Transformations in Drapetsona and Nea Kokkinia","citation":"Balkanologie (2021)","url":"https://doi.org/10.4000/balkanologie.2885","method":"Historical and ethnographic analysis of working-class refugee neighbourhoods in Piraeus.","finding":"The study connects rebetiko with neighbourhood life and refugee history, showing how music’s meaning is tied to migration, class and urban space."},{"kind":"Greek social history","title":"Did You Say Rebetiko? Musical Categories, Their Transformation, and Their Meanings","citation":"Journal of Social History (2018)","url":"https://doi.org/10.1093/jsh/shy031","method":"Historical analysis of changing names and categories for Greek popular music across the twentieth century.","finding":"The study traces how the label and social meaning of rebetiko changed over time."}],"flamenco":[{"kind":"Andalusian applied psychology study","title":"The Use of Flamenco with a Reflective Team in a Mothers’ School","citation":"Apuntes de Psicología (2020)","url":"https://apuntesdepsicologia.es/index.php/revista/en/article/view/795","method":"Mixed-design evaluation of pre- and post-programme measures in a parenting programme that included flamenco.","finding":"The study examined self-concept, anxiety, anger and depression in a local support setting."},{"kind":"Andalusian identity study","title":"Flamenco Identity: A Qualitative Case Study","citation":"ReiDoCrea (2021)","url":"https://www.ugr.es/~reidocrea/10-21.html","method":"Qualitative case study examining factors participants associate with flamenco identity.","finding":"The research treats flamenco identity as something formed through particular social and cultural connections."}],"argungu":[{"kind":"Argungu resident study","title":"Socio-Economic Impact of Recreational Fisheries among Residents of Argungu Community","citation":"Nigerian Journal of Fisheries (2023)","url":"https://www.ajol.info/index.php/naj/article/view/267717","method":"Study of residents’ views of recreational fisheries and the Argungu festival in Kebbi State, Nigeria.","finding":"Residents rated the view that the festival keeps culture alive highly, with a reported mean of 4.42."}],"gnawa":[{"kind":"Southeast Morocco ethnography","title":"Music for Healing: Black Gnawas and the Professional Practice of Dealing with Spirits in Southeastern Morocco","citation":"Social Compass (2022)","url":"https://journals.sagepub.com/doi/10.1177/00377686221111967","method":"Fieldwork from 2012 to 2016 in a Black Gnawa community in southeastern Morocco, including Khamlia and nearby villages.","finding":"The study describes healing ceremonies as social and musical work involving a ritual specialist, musicians and the person seeking help."},{"kind":"Gnawa healing ethnography","title":"Observations on Gnawa Healing in Morocco: Music, Bodies and the Circuit of Capital","citation":"Journal of African Cultural Studies (2012)","url":"https://intellectdiscover.com/content/journals/10.1386/pi.4.2.173_1","method":"Ethnographic analysis of Gnawa healing ceremonies and the relationships through which they are organised.","finding":"The account considers how ceremony joins spiritual interpretation with the labour and payment involved in staging it."}],"angklung":[{"kind":"Indonesian psychology study","title":"Can Angklung Become a Psychoeducative Instrument? An Exploratory Study of Angklung Players","citation":"Jurnal Psikologi Islam dan Budaya (2019)","url":"https://journal.uinsgd.ac.id/index.php/jpib/article/view/5574","method":"Exploratory qualitative study with seven angklung players.","finding":"The study considers angklung as a shared learning and psychoeducational practice."},{"kind":"Indonesian child study","title":"Effects of Playing Angklung and Practicing Silence on Emotion, Cognition and Oxytocin Levels in Children","citation":"Preliminary Indonesian study (2021)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8260063/","method":"Preliminary study of Indonesian elementary-school children combining angklung playing and silence practice with mood, cognition and oxytocin measures.","finding":"The study examines whether a locally rooted group music practice relates to measurable emotional and cognitive changes."}],"hudhud":[{"kind":"Ifugao oral-literature research","title":"Traces of Hudhud of the Itkak People in Ifugao","citation":"Oral Tradition (2020)","url":"https://www.tandfonline.com/doi/full/10.1080/0967828X.2020.1842799","method":"Ethnographic and oral-literature documentation focused on Hudhud varieties among Itkak and related Ifugao communities.","finding":"The research attends to local language varieties and performance contexts, showing why the chant is tied to communities, languages and occasions."}],"haenyeo":[{"kind":"Jeju health ethnography","title":"Health Care Experiences of Korean Women Divers (Jeju Haenyeos)","citation":"Qualitative Health Research (2018)","url":"https://pubmed.ncbi.nlm.nih.gov/29415636/","method":"Ethnographic study using snowball sampling with 15 Jeju haenyeo in 2016.","finding":"The authors describe an approach centred on listening to bodily and mental states, moderating effort and adjusting work for safe diving.","quote":"a life of listening to the body and mind, controlling greed, and adjusting work for safe diving","quoteAttribution":"The study authors’ summary of the haenyeo’s health-management approach"},{"kind":"Jeju skill-transmission ethnography","title":"The Ethnographic Study on Jeju Haenyeo and the Transfer of Their Muljil Skills","citation":"Korean Journal of Converging Humanities (2020)","url":"https://www.kci.go.kr/kciportal/ci/sereArticleSearch/ciSereArtiView.kci?sereArticleSearchBean.artiId=ART002589773","method":"Ethnographic study using in-depth interviews and participant observation in Jeju communities.","finding":"The study describes skills passing through maternal succession and wider village networks, including shared childcare and collective training."}],"kumbh-mela":[{"kind":"Allahabad longitudinal study","title":"Participation in Mass Gatherings Can Benefit Well-Being: Evidence from the 2011 Magh Mela","citation":"PLOS ONE (2012)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3474838/","method":"Questionnaire data collected before and after the 2011 Magh Mela from Kalpwasis and a control sample around Allahabad.","finding":"The Kalpwasi group showed increased reported well-being over time relative to controls. The design follows change, while pilgrimage participation includes several social and devotional elements."},{"kind":"Allahabad qualitative study","title":"Emic Understandings of Kumbh Mela Pilgrimage Experiences","citation":"Annals of Tourism Research (2014)","url":"https://www.sciencedirect.com/science/article/abs/pii/S0160738314000942","method":"Interpretive focus groups on pilgrims’ motivations, activities and experiences at the 2013 Kumbh Mela in Allahabad (Prayag), India.","finding":"Participants described pilgrimage through devotional practice, service, learning and social unity. The authors also examine how inequalities and stratification coexist with pilgrims’ sense of communitas.","quote":"Here we have divine experience.","quoteAttribution":"Pilgrim account quoted in the 2013 Kumbh Mela focus-group study."}],"reggae":[{"kind":"Kingston place-identity study","title":"“Trench Town Rock”: Reggae Music, Landscape Inscription, and the Making of Place in Kingston, Jamaica","citation":"Journal of Cultural Geography (2012)","url":"https://onlinelibrary.wiley.com/doi/10.1155/2012/585160","method":"Place-based analysis of murals and other inscriptions in Kingston’s Trench Town.","finding":"The study describes how reggae-related images shape or challenge outside narratives about Trench Town."}],"tango-argentina":[{"kind":"Buenos Aires dance ethnography","title":"Dancing Tango in Buenos Aires","citation":"Ethnochoreology and Dance Studies","url":"https://pure.qub.ac.uk/en/publications/dancing-tango-in-buenos-aires/","method":"Narrative ethnography based on dancing and observing milongas in Buenos Aires, with attention to researcher emotion and gendered interaction.","finding":"The account describes how vulnerability, invitation and gendered expectations are negotiated on the milonga floor."}],"tango-uruguay":[{"kind":"Montevideo tango ethnography","title":"Vida é Milonga: Exchange and Gift in Ritual Tango","citation":"Pontifical Catholic University of São Paulo ethnographic thesis","url":"https://repositorio.pucsp.br/handle/handle/19294","method":"Participant observation, interviews and informal conversations across tango gatherings in Buenos Aires and Montevideo.","finding":"The study treats the milonga as an urban ritual organised through exchange, gesture and social codes."}],"gaelic-stories":[{"kind":"Lewis and Glasgow language study","title":"Place Identity and Authenticity in Minority Language Revitalisation: Scottish Gaelic in Glasgow","citation":"International Journal of Bilingualism (2022)","url":"https://journals.sagepub.com/doi/10.1177/13670069221110382","method":"Speech analysis and interviews with 22 Glasgow pupils and 15 pupils on the Isle of Lewis, all aged 13–14.","finding":"Young speakers discussed accent and localness in ways that linked language to place and age. Some associated Lewis Gaelic with an older “granny voice.”","quote":"granny voice","quoteAttribution":"Description used by young speakers in the study when discussing Lewis Gaelic."}],"cornish-language":[{"kind":"Cornwall identity survey","title":"Cornish National Minority Status: Major Study 2024","citation":"Institute of Cornish Studies, University of Exeter (2024)","url":"https://www.exeter.ac.uk/research/centres/ics/research/culture/cornishnationalminoritystatusmajorstudy2024/","method":"Survey research with more than 2,200 respondents on Cornish identity, recognition and cultural participation.","finding":"Respondents reported strong attachment to Cornish identity; many connected recognition with cultural and linguistic pride."},{"kind":"Cornwall qualitative testimony","title":"Written Evidence on Cornish Language and Cultural Identity","citation":"UK Parliament evidence (2023)","url":"https://committees.parliament.uk/writtenevidence/119134/pdf/","method":"Qualitative written evidence including accounts from adult Cornish learners and community members.","finding":"One adult learner linked learning Cornish with joining in cultural regeneration.","quote":"if people lose language, I think that’s a great sadness","quoteAttribution":"Cornish learner quoted in the written evidence"}],"welsh-eisteddfod":[{"kind":"Welsh language-learning study","title":"Narratives of Belonging: Experiences of Learning and Using Welsh of Adult New Speakers in North West Wales","citation":"Bangor University research","url":"https://research.bangor.ac.uk/en/studentTheses/narratives-of-belonging-experiences-of-learning-and-using-welsh-o/","method":"Biographical narrative study carried out in north-west Wales between 2015 and 2019.","finding":"The research follows how Welsh-speaking identities are negotiated over time and in different social spaces."}],"barranquilla":[{"kind":"Barranquilla childhood study","title":"Cultural and Emotional Memory of Barranquilla Carnival in the Community–School Relationship","citation":"Revista Visión de Ciudad (2025)","url":"https://revistascientificas.cuc.edu.co/RVCDM/article/view/6512","method":"Qualitative ethnographic work using interviews, creative workshops and participatory mapping with children in selected neighbourhoods.","finding":"Children used symbolic maps and colour to represent what Carnival meant in their own local worlds."},{"kind":"Barranquilla child-participation study","title":"The Carnival of Barranquilla: An Opportunity to Show Who I Am, Express Myself and Be Seen","citation":"Revista Visión de Ciudad (2025)","url":"https://revistascientificas.cuc.edu.co/RVCDM/article/view/6513","method":"Local educational and cultural analysis centred on children’s perspectives and participation.","finding":"The paper treats children as participants in cultural identity-making."}],"qoylluriti":[{"kind":"Cusco pilgrimage ethnography","title":"The Glacier, the Rock, the Image: Emotional Experience and Semiotic Diversity at the Quyllurit’i Pilgrimage","citation":"Journal of Latin American and Caribbean Anthropology (2014)","url":"https://doi.org/10.1086/674324","method":"Ethnographic research in the bilingual Quechua–Spanish society of the southern Peruvian Andes.","finding":"The account follows how pilgrims encounter the glacier, rock and religious images through different systems of meaning."},{"kind":"Cusco urban-pilgrim ethnography","title":"Urban Pilgrims in Qoylluriti","citation":"Anthropologica (Peru)","url":"https://revistas.pucp.edu.pe/index.php/anthropologica/article/view/1315","method":"Ethnographic fieldwork over two years and two months with pilgrims from Cusco city.","finding":"The study examines how urban participants relate Indigenous religious practice to contemporary city life."}],"turkish-coffee":[{"kind":"Ankara interaction study","title":"Turkish Women’s Intimate Discourse in Coffee-Cup Readings","citation":"Discourse Studies (online first, 2024)","url":"https://journals.sagepub.com/doi/10.1177/14614456241252894","method":"Naturalistic recordings of coffee-cup readings among 25 Turkish-speaking women who were close friends, meeting informally in Ankara.","finding":"The analysis shows how a reading can shift conversational roles: a reader interprets images, comments on concerns and offers advice.","quote":"There isn’t just a single thing. I want to do lots of things.","quoteAttribution":"AHSEN, in a recorded coffee-reading conversation (English translation in the study)."}],"khon":[{"kind":"Thai movement study","title":"Balance in Khon Dancers and Non-Dancers","citation":"Thai movement research","url":"https://he01.tci-thaijo.org/index.php/JRTAN/article/view/15075","method":"Comparative study of Thai Khon dancers and non-dancers examining balance and postural control.","finding":"Research on physical performance describes the bodily demands of a masked dance alongside its dramatic and ceremonial meanings."}],"yoga":[{"kind":"Northern India ethnography","title":"Sādhus and Yoga: Embodied Practice in Northern India","citation":"SOAS ethnographic research","url":"https://eprints.soas.ac.uk/29179/","method":"Ethnographic research among sādhus in northern India, attending to bodily discipline, attention and religious practice.","finding":"The account situates yoga within ascetic and philosophical life."},{"kind":"India population study","title":"Yoga Practice in Rural and Urban India","citation":"Indian Journal of Community Medicine","url":"https://pubmed.ncbi.nlm.nih.gov/32310204/","method":"Study comparing yoga practice and related self-reported factors in rural and urban Indian populations.","finding":"The study offers local population context for how yoga practice is shaped by access and everyday setting."}],"nowruz":[{"kind":"Iranian Kurdistan visual ethnography","title":"Embodied Counter-Narratives: Newroz, Subjectivity and Cultural Visibility in Iranian Kurdistan","citation":"Visual ethnographic research (2025)","url":"https://portalrecerca.uab.cat/en/publications/embodied-counter-narratives-newroz-subaltern-subjectivity-and-the/","method":"Visual ethnography analysing photographs and video of Newroz celebrations in Iranian Kurdistan.","finding":"The study examines dress, dance and public space as ways people express Kurdish identity and political subjectivity."},{"kind":"Kurdish and Persian cultural study","title":"Newroz from Kurdish and Persian Perspectives","citation":"European Journal of Educational Sciences (2019)","url":"https://doi.org/10.29333/ejecs/318","method":"Qualitative comparison of cultural understandings of Newroz among Kurdish and Persian communities.","finding":"The paper records overlapping and distinct meanings associated with the festival."}],"kebaya":[{"kind":"Indonesian phenomenological study","title":"Embracing the New, Cherishing the Old: Gen X Indonesian Women and Modern Kebaya Design","citation":"Critical Studies in Fashion & Beauty (2025)","url":"https://intellectdiscover.com/content/journals/10.1386/cc_00092_1","method":"Phenomenological study of Indonesian women’s engagement with modern kebaya design.","finding":"The study examines how dress can carry cultural identity while adapting to present-day life."}],"ngondo":[{"kind":"Sawa historical study","title":"The Ngondo and Sawa Cultural Politics","citation":"Historical account (1973)","url":"https://www.persee.fr/doc/cea_0008-0055_1973_num_13_52_2710","method":"Historical analysis of the Ngondo’s public role in Douala and its changing relation to colonial and postcolonial power.","finding":"The account places the Ngondo within histories of Sawa political assertion and community organisation."}],"nguon":[{"kind":"Bamoun community record","title":"Nguon: Rituals of Governance in the Bamoun Community","citation":"UNESCO Intangible Cultural Heritage","url":"https://ich.unesco.org/en/RL/nguon-rituals-of-governance-and-associated-expressions-in-the-bamoun-community-01955","method":"Community nomination and safeguarding record based on knowledge of Nguon bearers and practitioners.","finding":"The record describes a festival through which Bamoun people gather, transmit knowledge and renew relations between people and ruler."},{"kind":"Bamoun cultural-geography monograph","title":"Le rituel Nguon chez les Bamoun du Cameroun: enjeux de patrimonialisation, stratégies identitaires et ambitions touristiques","citation":"L’Harmattan (2021)","url":"https://www.editions-harmattan.fr/catalogue/livre/le-rituel-nguon-chez-les-bamoun-du-cameroun/9248","method":"A 272-page cultural-geography study by University of Dschang researcher Armand Kpoumie Nchare, focused on Nguon, heritage-making, identity strategies and tourism.","finding":"The account follows Nguon across distinct audiences and historical periods, treating it as both a festival and a ritualisation of Bamoun custom and royal sacred authority."}],"gada":[{"kind":"Oromo governance record","title":"The Gada System: An Indigenous Democratic Socio-Political System of the Oromo","citation":"UNESCO Intangible Cultural Heritage","url":"https://ich.unesco.org/en/RL/gada-system-an-indigenous-democratic-socio-political-system-of-the-oromo-01164","method":"Oromo community heritage record on age grades, leadership rotation and public responsibilities.","finding":"The record describes governance as a learned social structure with obligations and transitions across the life course."}],"gusle":[{"kind":"Serbian ethnomusicology","title":"Gusle Female Players and Female Players on Traditional Instruments in Serbia: Identification by Sound","citation":"New Sound (2019)","url":"https://www.ojs.newsound.org.rs/index.php/NS/article/view/51","method":"Ethnomusicological analysis of women performers and traditional instrumental practice in Serbia.","finding":"The study addresses gender and sound in a field where performance has often been treated through male lineages."}],"kalela":[{"kind":"Zambia ethnography","title":"The Kalela Dance: Aspects of Social Relationships among Urban Africans","citation":"Clyde Mitchell, Rhodes-Livingstone Institute (1956)","url":"https://www.era.anthropology.ac.uk/Kalela/","method":"Classic ethnographic study of Kalela performed by migrants and residents on the Copperbelt in Zambia.","finding":"Mitchell used the dance to examine social relationships in urban life and affiliation in a changing setting."}],"fichee":[{"kind":"Sidama qualitative heritage study","title":"The Role of Folk Songs in Fiche-Chambalala Ceremony to Preserve Sidama Cultural Heritage","citation":"Addis Ababa University (2022)","url":"https://etd.aau.edu.et/items/f6603cf5-58a4-4414-970b-6dacffced5e7","method":"Qualitative study in Hawassa at Gudumalle using purposive interviews, focus-group discussions, non-participant observation and document review.","finding":"The study describes Fiche-Chambalaalla songs as ways to teach social conduct and pass on Sidama knowledge, stories and values. It distinguishes Qeexaala, Horre and Faro by performers, movement and musical form."}],"mangal":[{"kind":"Bangladesh visual-culture research","title":"Looking Through the Visual Culture of Mangal Shobhajatra in Bangladesh","citation":"Journal of Fine Arts & Culture (2024)","url":"https://du.ac.bd/index.php/webPost/80/22251","method":"Visual-culture analysis of the procession’s decorative objects across the period 1989–2023, reported by the University of Dhaka’s Department of Art History.","finding":"The paper treats the figures as active parts of political and cultural life, reading their visual identities as expressions of Bengali public culture, peace and shared humanity."}],"mahadra":[{"kind":"Mauritanian religious-education study","title":"The Struggle of Traditional Religious Education in West Africa: The Case of Mahdara in Mauritania","citation":"Journal of Ethnic and Cultural Studies (2019)","url":"https://doi.org/10.29333/ejecs/202","method":"Contextual analysis of the Mauritanian mahadra and debates about its educational role; the published abstract does not specify a participant sample or primary-data method.","finding":"The article situates mahadra within Mauritania’s religious and cultural identity and discusses pressures associated with state formation, climate, modernity and globalisation. It presents reform as a live debate among traditionalists, modernists and people seeking a middle ground."}],"cherokee-language":[{"kind":"Cherokee community health study","title":"The Health Effects of a Cherokee Grounded Culture and Leadership Program","citation":"International Journal of Environmental Research and Public Health (2022)","url":"https://www.mdpi.com/1660-4601/19/13/8018","method":"Thirty Remember the Removal participants, mainly young adults, completed surveys before, during and after the tribally created programme, with a six-month follow-up. Cherokee Nation and Eastern Band of Cherokee Indians institutional review boards approved the work.","finding":"The study reports improvements in mental-health measures and social-cultural connection at programme completion; Cherokee identity remained higher at follow-up. Participants also reported greater historical-loss thoughts while learning Cherokee history, alongside increased belonging and empowerment."}],"matariki":[{"kind":"New Zealand Māori longitudinal psychology study","title":"Indigenous Ethnic Identity, In-group Warmth, and Psychological Wellbeing: A Longitudinal Study of Māori","citation":"Current Psychology (2022)","url":"https://link.springer.com/article/10.1007/s12144-021-01636-4","method":"Seven annual assessments (2009–2015) of 3,803 Māori adults in the New Zealand Attitudes and Values Study, analysing ethnic-identity centrality, in-group warmth, life satisfaction, self-esteem and personal wellbeing.","finding":"Within-person increases in Māori in-group warmth and identity centrality predicted increases in wellbeing measures over time, while wellbeing also predicted later warmth. This is evidence about Māori identity and wellbeing, offering psychological context for Matariki’s themes of memory and belonging."}],"belgian-beer":[{"kind":"Belgian mixed-method public-health study","title":"Process Evaluation of the Belgian One-Month-Without-Alcohol Campaign, Tournée Minérale","citation":"BMC Public Health (2024)","url":"https://bmcpublichealth.biomedcentral.com/articles/10.1186/s12889-024-17941-z","method":"Belgian pre- and post-campaign questionnaires (n=49,022) combined with focus groups involving 31 adults, examining reach, experience, perceived effectiveness and maintenance.","finding":"Participants described social connectedness and a supportive environment as facilitators of abstaining for the month. Focus groups also showed how drinking and not drinking can reorganise café, restaurant and friendship routines."}]};
const NOTES={"ainu-dance":"Fieldwork in Mukawa and Sapporo shows why revitalisation is also a question of who controls how Ainu culture is learned, recorded and presented.","day-of-dead":"In Puebla, children encounter death through family accounts alongside Día de los Muertos observances, joining biological and spiritual meanings.","capoeira":"The Salvador study places the roda inside a psychosocial care service, where bodily skill, song, recognition and care meet within Afro-Brazilian practice.","kente":"Bonwire is a working weaving community. The cloth’s meanings are made and interpreted by makers whose knowledge includes technique, social use and the pressures of selling craft.","castells":"In Lleida, a human tower’s stages organise anticipation, shared physical effort and the emotional shift from tension to celebration.","argan":"Argan knowledge is tied to the tree’s ecology and to rural women’s cooperative work in south-west Morocco. Local research brings economic conditions into view alongside agency and social inclusion.","gnawa":"Khamlia fieldwork traces Gnawa music, spirit relations and healing expertise within Black Moroccan histories and a local ritual system.","haenyeo":"Jeju divers read breath, current and fatigue through experience; safe work depends on knowing when to stop as much as how to dive.","gaelic-stories":"Gaelic stories move through voice, family memory and contemporary institutions; archives shape which local voices remain audible.","cornish-language":"Cornish learners connect Kernewek with public recognition, family heritage and the availability of everyday spaces to use it.","welsh-eisteddfod":"Eisteddfodau place Welsh language and performance before a public audience; learners negotiate identity through belonging and access.","barranquilla":"Children’s maps and carnival accounts show how neighbourhoods, family participation and public visibility shape the festival’s meaning.","qoylluriti":"At Sinakara, glaciers, rocks and Christian images are encountered through Andean and Catholic frames; the place shapes the pilgrimage experience.","turkish-coffee":"In Ankara, 25 friends use cup patterns as prompts; playful interpretation lets future plans and private concerns enter intimate conversation.","nowruz":"In Iranian Kurdistan, Newroz gatherings put public space, dance and traditional clothing into conversation with seasonal renewal and Kurdish visibility.","kebaya":"Indonesian designers and wearers adapt kebaya through debates over heritage, fashion, gender and how continuity can be made present.","washoku":"New Year dishes concentrate seasonal timing and family preparation; shared recipes link sensory memory to intergenerational knowledge.","kimjang":"Coordinated preparation turns seasonal planning into mutual aid; who contributes and how help is returned shape the experience of reciprocity.","jang":"Fermentation makes time part of the technique: learners read ingredients and conditions through repeated observation alongside family knowledge.","sauna":"The sauna setting marks a social pause; its routines and shared etiquette shape how rest is negotiated in everyday life.","batik":"Regional motifs and contemporary adaptations carry distinct makers’ histories; pattern gives memory a material form that can travel.","yoga":"Indian yoga traditions link attention to movement, breath and philosophical reflection; present-day classes are one part of this wider history.","garba":"The devotional circle ties Navaratri participation to shared rhythm, making collective movement central to how the dance is learned.","french-meal":"French heritage descriptions centre celebratory meals on courses, presentation, shared time and conversation among participants.","tea":"In the documented Chinese tea traditions, serving and receiving create a paced social exchange shaped by local etiquette.","szopka":"Kraków’s nativity cribs turn local architecture into portable scenes; makers transform city landmarks into family and civic memory.","pizzaiuolo":"In Naples, craft learning hinges on close observation of timing, hand movements, dough and oven; expertise develops through practice and correction.","petrykivka":"Petrykivka makers pass on local brushwork and floral motifs; creating an image also teaches a distinctive artistic vocabulary.","argungu":"Argungu fishing depends on river conditions and specialist knowledge; the festival makes those skills visible within a shared history of river life.","isukuti":"Isukuti drumming coordinates movement and calls, giving Isukha and Idakho performers a way to carry social memory as audiences change.","barkcloth":"Among the Baganda, barkcloth moves through ceremony and social roles; its material history records changing community relationships.","fichee":"Sidama songs at Fichee-Chambalaalla teach social conduct and shared history through distinct performance forms, giving different generations roles in the celebration.","mbende":"Zezuru performers have carried Jerusarema into changing public settings; tourism, moral judgement and local livelihoods shape how it is staged.","zafimaniry":"Zafimaniry woodcarving carries knowledge into household architecture, linking craft, forest resources and belonging to place.","drametse":"The masked dance joins roles and narratives particular to eastern Bhutan; its social life depends on practitioners, teachers and performance occasions.","sbek-thom":"Khmer shadow theatre brings carved leather puppets together with epic narration, music and the community settings where stories are learned.","angklung":"A shared pitch emerges only when players coordinate individual instruments, making listening and timing part of the group’s musical form.","rukada-natya":"Rūkada Nātya gives village audiences a way to encounter familiar stories through puppets, humour and shared attention.","khon":"Khon’s masked roles draw on court theatre, dance, music and the Ramakien; its performance codes make social values visible.","hudhud":"Ifugao Hudhud recitation carries rice-cycle stories through a lead voice and chorus, linking memory to work, kinship and ritual time.","mangal":"The Dhaka procession’s crafted figures turn Bengali New Year into public visual speech, carrying peace and political identity through design.","naadam":"Mongolian archery, wrestling and horse racing bring spectatorship together with skill, local pride and intergenerational teaching.","dragon-boat":"Regional boat races tie the Dragon Boat Festival to local waterways, team organisation and inherited accounts of Qu Yuan.","reggae":"Kingston reggae joins musical form to neighbourhood history; artists use lyrics and performance to make political claims audible.","taquile":"Taquile textiles encode local time through patterns worn in daily life, making a community calendar visible on the body.","tango-uruguay":"Montevideo tango shares a Río de la Plata heritage while its venues, accents and stories take shape in Uruguay’s own cultural life.","joumou":"Haitian joumou soup recalls the post-revolutionary right to eat a dish once denied to enslaved people; preparing and sharing it renews that history.","mariachi":"Mariachi ensembles adapt repertoire and instrumentation across regional traditions, carrying migration and public memory through performance.","frevo":"Recife’s frevo grew through street processions, music, dance and popular associations; acrobatics express an urban practice made in motion.","cherokee-language":"Cherokee language revitalisation is led by Cherokee Nation through immersion, teaching and tribally directed programmes grounded in sovereignty.","budj-bim":"Gunditjmara aquaculture at Budj Bim shows how engineered waterways and stone structures hold ecological knowledge within Country.","matariki":"Matariki links star knowledge with seasonal calendars and remembrance; iwi and hapū maintain distinct teachings about the year's turning.","vanuatu-sand":"Vanuatu sand drawing turns a continuous line into a learned visual text, with local knowledge carried by the maker’s sequence of marks.","tonga-lakalaka":"Lakalaka brings voices and movement into a formal group performance where poetic leadership coordinates a community’s response.","ebru":"Ebru makers work with pigment on water, where timing, tools and touch shape each pattern; expertise includes managing the medium’s movement.","dutch-millers":"Dutch millers coordinate machinery, water levels, weather and maintenance; technical skill remains embedded in community cooperation.","tahteeb":"Upper Egyptian practitioners use shared rules to structure stick-play competition, with the tahteeb stick carrying meanings of manhood and respect.","kankurang-senegal":"Manding initiation connects young people, elders and forest settings through knowledge whose access is organised by community roles.","kankurang-gambia":"In Manding communities across The Gambia, Kankurang carries shared heritage through local custodians, histories and initiation settings.","mongolian-calligraphy":"Traditional Mongolian script is learned through repeated brush movement and teacher correction; institutions shape whether skill reaches younger writers.","belgian-beer":"Belgian beer culture joins brewing knowledge with cafés and social spaces; local research also shows social norms shape drinking decisions.","kabuki":"Kabuki’s stylised movement, costume and actor lineages make dramatic roles legible through inherited theatrical technique.","mahadra":"Mauritanian mahadra circles transmit religious texts through listening, recitation and memorisation, adapting instruction to community settings.","xeer-ciise-djibouti":"Somali-Issa customary law frames dispute repair through negotiation, compensation and relationships among clans, grounded in local authority.","xeer-ciise-somalia":"Somali-Issa customary law organises dispute settlement through community relationships and negotiated obligations within a specific local history.","gada":"Gada organises Oromo leadership through rotating age-sets and public responsibilities, giving governance a rhythm of succession and accountability.","ngondo":"Sawa communities gather around the Wouri River for Ngondo, where ritual, memory and collective concerns meet within local political history.","nguon":"Bamoun Nguon combines royal ritual with public consultation, placing questions about authority inside the community’s ceremonial calendar.","mvet-oyeng":"Ekang mvet performers sustain epic knowledge through skilled narration, music and shared listening, keeping memory alive in company.","mwazindika":"Daida mwazindika joins dance and ritual in a community setting where participants connect movement with spiritual and social meaning.","xoe":"Tai xòe’s linked circle dances teach shared timing through repeated movement, with local forms carrying particular music and social roles.","compas":"Haitian compas grew through dance-band innovation and urban social life, where rhythmic participation makes music a shared public space.","palenque-kuagro":"In Palenque de San Basilio, kuagro peer groups organise mutual help across life stages, linking friendship with community responsibility.","washi":"Washi paper making relies on knowledge of plant fibres, water, season and repeated handwork passed between experienced makers and learners.","gusle":"Serbian gusle singers perform epic verse before listeners, where voice and musical timing give stories a role in public memory.","khoomei":"Mongolian throat-singing traditions use vocal technique shaped by local lineages and soundscapes; listening connects performance with place.","sebeiba":"At Djanet, Sebeïba brings Tuareg groups into a public ritual contest whose shared rules turn rivalry into collective celebration.","khidr-feast":"Along the Tigris, Khidr Elias gatherings link vows, food and visits to sacred sites, making remembrance a shared social act.","visoko-singing":"Dolen and Satovcha choirs learn multipart singing through collective practice that makes village identity audible.","xooy":"Serer Xooy gatherings centre trained diviners whose interpretations give communities a public way to discuss uncertain futures.","joking-relationships":"Among the Niger communities described, joking relations establish reciprocal duties that shape how people approach tension and conflict.","guarania":"Guarania carries Paraguayan language and history through a song form shaped by local composers, audiences and diaspora connections.","intore":"Rwandan Intore troupe training connects precise movement with music and group identity across changing stages of public performance.","kalela":"Kalela’s urban performance in Zambia uses dance and dress to stage local social relations as performers learn by watching and joining.","light-rum-masters":"Cuban light-rum master blenders rely on long apprenticeship and sensory judgement to maintain a craft built through collective expertise.","henna-rituals":"Henna designs are made within varied family and ceremony settings; the work can organise shared care and mark the passage into an occasion.","pysanka-estonia":"Ukrainian pysanka motifs are formed through wax and dye as family designs carry wishes and memory across generations and diaspora."};
